using System.Collections.Generic;
using UnityEngine;

namespace WarMission
{
    public enum CoverHeight
    {
        /// <summary>Waist-high: crouch behind it, stand up to shoot over it.</summary>
        Low,
        /// <summary>Taller than the soldier: stand at the corner, step out sideways to shoot.</summary>
        High,
    }

    /// <summary>
    /// A spot next to cover. Forward points at the cover (toward the threat side). One soldier at a time.
    /// Generated by War Mission > Generate Cover Points, or placed by hand.
    /// </summary>
    public class CoverPoint : MonoBehaviour
    {
        static readonly List<CoverPoint> all = new List<CoverPoint>();

        [SerializeField] CoverHeight height = CoverHeight.Low;
        [Tooltip("High cover: side to step out to when peeking (-1 left, +1 right as seen facing the cover).")]
        [SerializeField] int peekSide;
        [Tooltip("Threats more than this many degrees off Forward are not covered.")]
        [SerializeField] float protectionAngle = 65f;

        public static IReadOnlyList<CoverPoint> All => all;
        public CoverHeight Height => height;
        public int PeekSide => peekSide;
        public Vector3 Position => transform.position;
        public Vector3 Forward => transform.forward;
        public Object Occupant { get; private set; }

        public bool IsFreeFor(Object who) => Occupant == null || Occupant == who;

        public bool TryClaim(Object who)
        {
            if (!IsFreeFor(who)) return false;
            Occupant = who;
            return true;
        }

        public void Release(Object who)
        {
            if (Occupant == who) Occupant = null;
        }

        /// <summary>True when a threat at this position is on the covered side.</summary>
        public bool Protects(Vector3 threat)
        {
            Vector3 to = threat - Position;
            to.y = 0f;
            return to.sqrMagnitude > 0.01f && Vector3.Angle(Forward, to) <= protectionAngle;
        }

        /// <summary>Where to stand to shoot: the point itself (low) or a step out past the corner (high).</summary>
        public Vector3 PeekPosition(float stepOut) =>
            height == CoverHeight.High && peekSide != 0 ? Position + transform.right * (peekSide * stepOut) : Position;

        public void Configure(CoverHeight coverHeight, int side)
        {
            height = coverHeight;
            peekSide = side;
        }

        void OnEnable() => all.Add(this);
        void OnDisable()
        {
            all.Remove(this);
            Occupant = null;
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() => all.Clear();

        void OnDrawGizmos()
        {
            Gizmos.color = Occupant != null ? Color.red : height == CoverHeight.Low ? new Color(0.2f, 0.9f, 0.3f) : new Color(0.3f, 0.6f, 1f);
            Vector3 p = Position + Vector3.up * 0.05f;
            Gizmos.DrawWireSphere(p, 0.2f);
            Gizmos.DrawLine(p, p + Forward * 0.5f);
            if (height == CoverHeight.High && peekSide != 0) Gizmos.DrawLine(p, PeekPosition(0.9f) + Vector3.up * 0.05f);
        }
    }
}
